#!/usr/bin/env node
/**
 * docs-complete (plan 13.1): every feature has a page, in English and Hebrew.
 *
 * 1. Every page the docs sidebar links to (docs/astro.config.mjs, `slug:`)
 *    exists in English (docs/src/content/docs/<slug>.md[x]) and in Hebrew
 *    (docs/src/content/docs/he/<slug>.md[x]).
 * 2. Every page in an autogenerated sidebar directory has its Hebrew twin.
 * 3. Every area plan 13.1.1 names (docs/required-pages.json `areas`) maps to
 *    a page that is in the sidebar.
 * 4. A page another open PR writes is listed in `pending` with that PR; it
 *    is exempt from 1 until it lands, and listing a page that already
 *    exists is an error (the exemption must be removed).
 *
 * Run: `npm run docs:complete`. Exits 1 with one line per problem.
 */
import { existsSync, readFileSync, readdirSync } from "node:fs";
import { join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

/** Sidebar slugs and autogenerated directories in an astro.config source. */
export function sidebarOf(src) {
  const slugs = [...src.matchAll(/\bslug:\s*"([^"]+)"/g)].map((m) => m[1]);
  const dirs = [...src.matchAll(/autogenerate:\s*\{\s*directory:\s*"([^"]+)"/g)].map((m) => m[1]);
  return { slugs, dirs };
}

/** The problems for a docs tree; `has(rel)` says whether docs/src/content/docs/<rel> exists, `list(dir)` lists a directory. */
export function check({ config, required, has, list }) {
  const problems = [];
  const page = (slug, lang) => ["md", "mdx"].some((ext) => has(`${lang === "he" ? "he/" : ""}${slug}.${ext}`));
  const { slugs, dirs } = sidebarOf(config);
  const pending = required.pending ?? {};
  for (const slug of slugs) {
    if (pending[slug]) {
      if (page(slug, "en")) problems.push(`${slug}: is listed as pending (${pending[slug]}) but the page exists — remove it from docs/required-pages.json "pending"`);
      continue;
    }
    if (!page(slug, "en")) problems.push(`${slug}: in the sidebar, but there is no English page (docs/src/content/docs/${slug}.md)`);
    if (!page(slug, "he")) problems.push(`${slug}: no Hebrew page (docs/src/content/docs/he/${slug}.md)`);
  }
  for (const slug of Object.keys(pending)) if (!slugs.includes(slug)) problems.push(`${slug}: pending, but not in the sidebar`);
  for (const dir of dirs) {
    for (const name of list(dir)) {
      if (!/\.mdx?$/.test(name)) continue;
      if (!has(`he/${dir}/${name}`)) problems.push(`${dir}/${name}: no Hebrew page (docs/src/content/docs/he/${dir}/${name})`);
    }
  }
  for (const [area, slug] of Object.entries(required.areas ?? {})) {
    if (!slugs.includes(slug)) problems.push(`area "${area}": its page ${slug} is not in the sidebar`);
  }
  return problems;
}

function main() {
  const ROOT = resolve(fileURLToPath(new URL("..", import.meta.url)));
  const DOCS = join(ROOT, "docs/src/content/docs");
  const problems = check({
    config: readFileSync(join(ROOT, "docs/astro.config.mjs"), "utf8"),
    required: JSON.parse(readFileSync(join(ROOT, "docs/required-pages.json"), "utf8")),
    has: (rel) => existsSync(join(DOCS, rel)),
    list: (dir) => (existsSync(join(DOCS, dir)) ? readdirSync(join(DOCS, dir)) : []),
  });
  if (problems.length) {
    console.error(problems.join("\n"));
    console.error(`\n✗ docs-complete: ${problems.length} problem(s)`);
    process.exit(1);
  }
  process.stdout.write("✓ docs-complete: every sidebar page exists in English and Hebrew; every 13.1.1 area has a page\n");
}

if (import.meta.url.startsWith("file:") && process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) main();
